### 5.3 Database Indexes

```sql
-- Primary Keys (auto-indexed)
CREATE INDEX idx_aria_ratings_pkey ON aria_ratings(id);
CREATE INDEX idx_governance_ratings_pkey ON governance_ratings(id);

-- Foreign Keys
CREATE INDEX idx_governance_ratings_review_id ON governance_ratings(review_id);

-- Query Optimization
CREATE INDEX idx_aria_ratings_username ON aria_ratings(username);
CREATE INDEX idx_aria_ratings_created_at ON aria_ratings(created_at);
CREATE INDEX idx_governance_ratings_username ON governance_ratings(username);
CREATE INDEX idx_governance_ratings_created_at ON governance_ratings(created_at);
CREATE INDEX idx_rating_statistics_service_date ON rating_statistics(service_type, rating_date);
```

